-- Refer to https://wiki.hyprland.org/Configuring/Variables/

-- https://wiki.hyprland.org/Configuring/Variables/#general

hl.curve("myBezier", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.05 } } })
hl.animation({
  leaf = "windows",
  enabled = true,
  speed = 0.7,
  bezier = "myBezier",
  style = "slide",
})
hl.animation({
  leaf = "windowsOut",
  enabled = true,
  speed = 0.7,
  bezier = "myBezier",
  style = "popin 80%",
})
hl.animation({
  leaf = "fade",
  enabled = true,
  speed = 5,
  bezier = "default",
})
hl.animation({
  leaf = "workspaces",
  enabled = true,
  speed = 1,
  bezier = "default",
})

hl.gesture({
  fingers = 3,
  direction = "horizontal",
  action = "workspace",
})

hl.device({
  name = "steelseries-steelseries-rival-3",
  sensitivity = -0.60,
})

hl.device({
  name = "elan0752:00-04f3:31c2-touchpad",
  sensitivity = 0.1,
  natural_scroll = true,
})

hl.device({
  name = "logitech-logig-tkl-mkeyboard",
})

hl.window_rule({
  match = {
    class = ".*Nsxiv.*",
  },
  float = true,
  size = "50% 60%",
})

hl.window_rule({
  name = "Discord",
  match = {
    class = "discord",
  },
  workspace = "name:D",
  no_initial_focus = true,
})

hl.window_rule({
  match = {
    class = "jetbrains(.*)",
  },
  opaque = true,
})

hl.window_rule({
  name = "kalk",
  match = {
    class = ".*kalk.*",
  },
  float = true,
  move = "(monitor_w-window_w-(window_w*0.3)) (monitor_h*0.03)",
  size = "(monitor_w*0.2) (monitor_h*0.5)",
})

hl.window_rule({
  name = "nemo",
  match = {
    class = ".*nemo.*",
  },
  float = true,
  move = "(monitor_w-window_w-(window_w*0.09)) (window_h*0.06)",
  size = "(monitor_w*0.45) (monitor_h*0.6)",
})

